import { existsSync, readdirSync, statSync, openSync, readSync, closeSync } from "node:fs";
import { join } from "node:path";
import { homedir } from "node:os";

import { loadCache, saveCache } from "./cache";
import type { ActivityCache, CwdOutbox, ToolRecord } from "./types";

export interface ScanOptions {
  sessionsRoot?: string;
  cachePath?: string;
  windowHours?: number;
}

const DEFAULT_SESSIONS_ROOT = join(homedir(), ".pi", "agent", "sessions");

export function encodeCwd(cwd: string): string {
  const normalized = cwd.replace(/\/+$/, "");
  if (!normalized || normalized === "/") return "---";
  return `--${normalized.slice(1).replace(/\//g, "-")}--`;
}

/** Extract MCP server name from mcp_hub_* tool name */
export function extractMcpServer(toolName: string): string | null {
  if (!toolName.startsWith("mcp_hub_")) return null;
  // mcp_hub_gitnexus_impact → gitnexus
  // mcp_hub_websearch-exa_web_search_exa → websearch-exa
  const rest = toolName.slice("mcp_hub_".length);
  // Split on first _ that's followed by a verb/action
  const parts = rest.split("_");
  if (parts.length <= 1) return rest;
  // Heuristic: server name is everything before the last action segment
  // e.g., gitnexus_impact → server=gitnexus
  // e.g., websearch-exa_web_search_exa → server=websearch-exa
  // e.g., zread_search_doc → server=zread
  // The server part never contains underscores (they use - for compound names)
  // So find the first part that contains no dash and is followed by more parts
  return parts[0];
}

